/* ---------- navigation ---------- */
function go(v){
  document.querySelectorAll('.view').forEach(s=>s.classList.remove('active'));
  document.getElementById('v-'+v).classList.add('active');
  document.querySelectorAll('.tab').forEach(t=>{ t.classList.toggle('active',t.dataset.v===v); if(t.dataset.v===v){ const sp=t.querySelector('span'); const mc=document.getElementById('menu-cur'); if(sp&&mc) mc.textContent=sp.textContent; } });
  closeMenu();
  if(v==='ringkasan') renderRingkasan();
  if(v==='proyek'){ renderProyekBanner(); refreshProjects(); }
  if(v==='analisis') renderAnalisis();
  if(v==='gambar'){ renderGambar(); renderPlans(); }
  if(v==='admin') renderAdmin();
  if(v==='laporan'){ renderRingkasan(); renderTag(); }   /* B1: ringkasan sebelumnya tidak pernah dirender */
  if(v==='beban') computeLL();
  if(v==='duty') computeAnalisis();
  if(v==='material'){ renderAnalisis(); computeAnalisis(); }
  if(v==='analisis') computeAnalisis();
  if(v==='jsa') renderJSA();
  if(v==='tentang') renderChangelog();
  window.scrollTo({top:0,behavior:reducedMotion()?'auto':'smooth'});
}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>go(t.dataset.v)));

/* ---------- stats ---------- */
function stats(){
  let total=0,ans=0,ok=0,no=0,na=0,crit=0,critFail=0,naMissing=0;
  const sec=[];
  DATA.forEach((s,si)=>{
    let T=0,A=0,O=0,N=0,X=0,C=0,CF=0;
    s.items.forEach((it,ii)=>{
      total++;T++; if(it.c){crit++;C++;}
      const a=ansOf(si,ii);
      if(a==='na' && it.c && !naNoteOf(si,ii)){ naMissing++; return; }   /* E12: N/A kritis tanpa alasan = belum dinilai */
      if(a){ans++;A++;}
      if(a==='ok'){ok++;O++;}
      else if(a==='no'){no++;N++; if(it.c){critFail++;CF++;}}
      else if(a==='na'){na++;X++;}
    });
    sec.push({code:s.code,title:s.title,T,A,O,N,X,C,CF});
  });
  let status = ans<total ? 'BELUM LENGKAP' : critFail>0 ? 'MERAH' : no>0 ? 'KUNING' : 'HIJAU';
  return {total,ans,ok,no,na,crit,critFail,naMissing,sec,status};
}

/* ---------- checklist render ---------- */
function itemHTML(si,ii){
  const it=DATA[si].items[ii], key=si+'-'+ii, auto=autoNA(si), a=ansOf(si,ii)||'', dis=auto?' disabled':'';
  const needNote = a==='na' && it.c && !auto;
  const noteHTML = needNote ? '<div class="na-note'+(naNoteOf(si,ii)?'':' is-missing')+'"><label for="na-'+key+'">Alasan N/A <span>wajib untuk butir kritis</span></label><input id="na-'+key+'" maxlength="300" autocomplete="off" value="'+esc(state.naNote[key]||'')+'" placeholder="Jelaskan mengapa butir ini tidak berlaku" oninput="setNaNote(\''+key+'\',this.value)"></div>'
    : (auto ? '<div class="na-auto">Otomatis N/A — tidak berlaku untuk perancah tubular.</div>' : '');
  const rowcls = a==='ok'?'row-ok':a==='no'?'row-no':a==='na'?'row-na':'';
  const hp = safeImg(state.photos[key]);
  const lbl = DATA[si].code+' butir '+(ii+1);
  return `<div class="item ${rowcls}" id="item-${key}">
    <div class="it-main">
      <div class="it-txt" id="it-txt-${key}">${it.t}</div>
      <div class="it-meta">${it.c?'<span class="badge-crit">Kritis</span>':''}<span class="badge-ref">${it.ref}</span><button type="button" class="photo-btn" onclick="pickPhoto('${key}')" aria-label="${hp?'Ganti foto bukti':'Tambah foto bukti'}, ${lbl}">${hp?'Ganti foto':'+ Foto bukti'}</button></div>
      ${hp?`<div class="thumb-wrap"><img class="thumb" src="${hp}" alt="Foto bukti ${lbl}"><button type="button" class="thumb-x" onclick="removePhoto('${key}')" aria-label="Hapus foto bukti, ${lbl}">Hapus</button></div>`:''}
      ${noteHTML}
    </div>
    <div class="ans" role="group" aria-labelledby="it-txt-${key}">
      <button type="button" class="ab ${a==='ok'?'sel-ok':''}" aria-pressed="${a==='ok'}" onclick="setA('${key}','ok')"${dis}>Sesuai</button>
      <button type="button" class="ab ${a==='no'?'sel-no':''}" aria-pressed="${a==='no'}" onclick="setA('${key}','no')"${dis}>Tidak</button>
      <button type="button" class="ab ${a==='na'?'sel-na':''}" aria-pressed="${a==='na'}" onclick="setA('${key}','na')"${dis}>N/A</button>
    </div>
  </div>`;
}
function renderChecklist(){
  const root=document.getElementById('checklist-root');
  root.innerHTML = DATA.map((s,si)=>{
    const items = s.items.map((it,ii)=> itemHTML(si,ii)).join('');
    return `<div class="sec-block">
      <div class="sec-head"><div class="sec-code">${s.code}</div><h3>${s.title}</h3><div class="sec-score" id="score-${si}"></div></div>
      ${autoNA(si)?'<p class="sec-note">Kategori ini otomatis N/A untuk perancah tubular. Butir tetap ditampilkan sebagai rujukan.</p>':''}
      <div class="items">${items}</div>
    </div>`;
  }).join('');
  updateScores();
}
function setA(key,val){
  const p=key.split('-'), si=parseInt(p[0],10), ii=parseInt(p[1],10);
  if(autoNA(si)) return;
  state.answers[key] = state.answers[key]===val ? undefined : val;
  const a=state.answers[key]||'';
  const row=document.getElementById('item-'+key);
  if(row && DATA[si].items[ii].c){
    /* butir kritis: baris dirender ulang agar isian alasan N/A muncul/hilang; fokus dipertahankan */
    refreshItem(key);
    const fo = a==='na' ? document.getElementById('na-'+key) : document.querySelector('#item-'+key+' .ab:nth-child('+(val==='ok'?1:val==='no'?2:3)+')');
    if(fo) fo.focus();
  } else if(row){
    row.className='item '+(a==='ok'?'row-ok':a==='no'?'row-no':a==='na'?'row-na':'');
    const bs=row.querySelectorAll('.ab');
    bs.forEach(b=>{b.className='ab'; b.setAttribute('aria-pressed','false');});
    if(a){ const map={ok:'sel-ok',no:'sel-no',na:'sel-na'}; const b=bs[a==='ok'?0:a==='no'?1:2]; b.classList.add(map[a]); b.setAttribute('aria-pressed','true'); }
  }
  updateScores(); save();
}
function bulk(val){
  DATA.forEach((s,si)=>s.items.forEach((it,ii)=>{ state.answers[si+'-'+ii] = val?val:undefined; }));
  if(!val) state.naNote={};
  renderChecklist(); save();
}
function updateScores(){
  const st=stats();
  st.sec.forEach((s,si)=>{
    const el=document.getElementById('score-'+si);
    if(el) el.textContent = `${s.O}/${s.T} sesuai`+(s.N?` · ${s.N} tidak`:'');
  });
  document.getElementById('prog-txt').textContent = `${st.ans} / ${st.total} item terjawab`+(st.naMissing?` · ${st.naMissing} N/A kritis tanpa alasan`:'');
  const pct = st.total? Math.round(st.ans/st.total*100):0;
  const fill=document.getElementById('prog-fill'); fill.style.width=pct+'%';
  fill.style.background = st.status==='MERAH'?VERDICT.MERAH.c : st.status==='KUNING'?VERDICT.KUNING.c : st.status==='HIJAU'?VERDICT.HIJAU.c : 'var(--ink)';
  setChip('prog-verdict',st.status);
  updateHeadChip();
}
/* chip status di bilah menu = status akhir (checklist + analisis struktur indikatif), sama dengan tag dan PDF */
function updateHeadChip(){
  const el=document.getElementById('head-verdict'); if(!el) return;
  const F=finalView();
  setChip('head-verdict',F.status);
  if(F.hold) el.textContent='KUNING · DESAIN';
  el.title='Status akhir — checklist inspeksi: '+F.st.status+'; analisis struktur indikatif: '+(F.A.ok?'lolos':'perlu review');
}
function setChip(id,status){
  const el=document.getElementById(id); if(!el)return;
  const v=VERDICT[status];
  el.textContent = status;
  if(status==='BELUM LENGKAP'){ el.style.background='var(--grey-bg)'; el.style.color='var(--steel)'; }
  else { el.style.background=v.c; el.style.color=inkOn(v.c); }
}

/* ---------- status akhir: checklist inspeksi + analisis struktur indikatif (v2.4.0) ---------- */
/* Tag, ringkasan, banner Data Proyek, dan PDF tidak boleh menyatakan "aman digunakan" bila analisis
   struktur indikatif berstatus PERLU REVIEW: checklist HIJAU/KUNING + analisis PERLU REVIEW →
   KUNING "menunggu verifikasi desain". Chip progres checklist tetap menunjukkan hasil checklist saja. */
function finalView(){
  const st=stats(), A=analisisData();
  const nCek=A.checks.filter(function(c){return !c.ok;}).length;
  let status=st.status, hold=false;
  if((status==='HIJAU'||status==='KUNING') && !A.ok){ status='KUNING'; hold=true; }
  const v=VERDICT[status];
  const label=hold ? 'KUNING — Menunggu Verifikasi Desain' : v.label;
  const desc=hold ? 'Checklist inspeksi '+(st.status==='HIJAU'?'terpenuhi':'berstatus KUNING')+', tetapi analisis struktur indikatif (Beta) berstatus PERLU REVIEW: '+nCek+' pemeriksaan CEK. Jangan dibebani sesuai kelas beban sampai desain diverifikasi ahli perancah yang kompeten.' : v.desc;
  return {status:status, hold:hold, st:st, A:A, nCek:nCek, v:v, label:label, desc:desc, c:v.c};
}
function anLine(F){ return 'Analisis struktur indikatif (Beta): '+(F.A.ok?'LOLOS PEMERIKSAAN INDIKATIF':'PERLU REVIEW — '+F.nCek+' pemeriksaan CEK'); }

/* ---------- proyek banner ---------- */
function renderProyekBanner(){
  const F=finalView(), st=F.st;
  document.getElementById('banner-proyek').innerHTML =
    `<div class="verdict-banner" style="--vc:${F.c};--vi:${inkOn(F.c)}">
       <div class="vb-icon">${F.status==='HIJAU'?'✓':F.status==='MERAH'?'✕':F.status==='KUNING'?'!':'…'}</div>
       <div class="vb-txt"><h2>${F.label}</h2><p>${st.ans}/${st.total} item terjawab · ${st.critFail} item kritis gagal. ${F.desc}</p></div>
     </div>`;
}

/* ---------- ringkasan ---------- */
function renderRingkasan(){
  const F=finalView(), st=F.st;
  const rows = st.sec.map(s=>{
    const app_=s.T-s.X, pct = app_>0? Math.round(s.O/app_*100)+'%' : 'N/A';   /* skor = sesuai ÷ butir yang berlaku (N/A tidak dihitung) */
    const col = s.CF>0?'var(--red)':s.N>0?'var(--amber)':s.A<s.T?'var(--mute)':'var(--green)';
    return `<tr><td><b>${s.code}</b> ${s.title}</td><td class="num">${s.O}</td><td class="num">${s.N}</td><td class="num">${s.X}</td><td class="num">${s.A}/${s.T}</td><td><span class="dot" style="background:${col}"></span>${pct}</td></tr>`;
  }).join('');
  // findings
  let finds='';
  let naList='';
  DATA.forEach((s,si)=>s.items.forEach((it,ii)=>{
    const a=ansOf(si,ii);
    if(a==='no')
      finds += `<div class="find ${it.c?'':'warn'}"><div class="fc">${s.code}${it.c?' KRITIS':''}</div><div class="ft">${it.t}</div></div>`;
    if(a==='na' && it.c && !autoNA(si))
      naList += `<div class="find na-row"><div class="fc">${s.code} N/A</div><div class="ft">${it.t}<span class="na-why">${naNoteOf(si,ii)?'Alasan: '+esc(naNoteOf(si,ii)):'Alasan belum diisi — butir dianggap belum dinilai.'}</span></div></div>`;
  }));
  if(!finds) finds = `<div class="empty">Tidak ada temuan "Tidak Sesuai". ✓</div>`;
  const rec = F.status==='MERAH' ? 'Perbaiki seluruh item kritis yang gagal, lalu lakukan inspeksi ulang sebelum perancah boleh digunakan. Pasang tag MERAH (Do Not Use).'
            : F.hold ? 'Checklist inspeksi belum cukup untuk menyatakan perancah aman: analisis struktur indikatif masih berstatus PERLU REVIEW. Tutup setiap butir CEK di Tahap 3 dan Tahap 6 atau minta verifikasi desain oleh ahli perancah yang kompeten; selama itu pasang tag KUNING (menunggu verifikasi desain).'
            : F.status==='KUNING' ? 'Tindak lanjuti temuan non-kritis. Penggunaan terbatas dapat dipertimbangkan oleh supervisor; pasang tag KUNING (Incomplete) hingga tuntas.'
            : F.status==='HIJAU' ? 'Perancah memenuhi seluruh kriteria checklist dan pemeriksaan indikatif. Pasang tag HIJAU dan catat jadwal pemeriksaan ulang ≤ 7 hari. Hasil analisis bersifat indikatif (Beta) dan bukan sertifikasi desain.'
            : 'Lengkapi seluruh item pada tab Checklist untuk memperoleh verdict akhir dan rekomendasi.';
  document.getElementById('ringkasan-root').innerHTML = `
    <div class="verdict-banner" style="--vc:${F.c};--vi:${inkOn(F.c)}">
      <div class="vb-icon">${F.status==='HIJAU'?'✓':F.status==='MERAH'?'✕':F.status==='KUNING'?'!':'…'}</div>
      <div class="vb-txt"><h2>${F.label}</h2><p>${F.desc}</p></div>
    </div>
    <p class="verdict-basis"><span>Checklist inspeksi: <b>${st.status}</b></span><span>${anLine(F)}</span></p>
    <div class="stats">
      <div class="stat"><div class="n">${st.total}</div><div class="l">Total Item</div></div>
      <div class="stat"><div class="n" style="color:var(--green)">${st.ok}</div><div class="l">Sesuai</div></div>
      <div class="stat"><div class="n" style="color:var(--red)">${st.no}</div><div class="l">Tidak Sesuai</div></div>
      <div class="stat"><div class="n" style="color:var(--mute)">${st.na}</div><div class="l">N/A</div></div>
      <div class="stat"><div class="n" style="color:${st.critFail?'var(--red)':'var(--green)'}">${st.critFail}/${st.crit}</div><div class="l">Kritis Gagal</div></div>
    </div>
    <div class="card">
      <h3>Skor per Kategori</h3>
      <table><thead><tr><th>Kategori</th><th class="num">Sesuai</th><th class="num">Tidak</th><th class="num">N/A</th><th class="num">Terjawab</th><th>Skor</th></tr></thead><tbody>${rows}</tbody></table>
    </div>
    <div class="card">
      <h3>Temuan (Tidak Sesuai)</h3>${finds}
    </div>
    ${naList?`<div class="card"><h3>N/A pada Butir Kritis</h3><p class="note">Setiap N/A pada butir kritis wajib beralasan dan ikut tercetak di laporan PDF.</p>${naList}</div>`:''}
    <div class="card">
      <h3>Rekomendasi</h3><p class="lead">${rec}</p>
      <div class="btn-row"><button type="button" class="btn btn-dark" data-pdf-btn onclick="buildPDF()">↓ Buat Laporan PDF</button></div>
    </div>`;
}

/* ---------- tag ---------- */
function val(id){return (document.getElementById(id)||{}).value||'';}
function tagHTML(){
  const F=finalView(), st=F.st, A=F.A, status=F.status;
  const tgl = val('f-tanggal')?localDate(val('f-tanggal')).toLocaleDateString('id-ID'):'—';
  const next = (()=>{ const d=val('f-tanggal'); if(!d)return '—'; const dt=localDate(d); dt.setDate(dt.getDate()+7); return dt.toLocaleDateString('id-ID'); })();
  const D=A.d; const kgBay=Math.round(D.kn*1000/9.80665);
  const tagno = esc(val('f-tag')||'SC-—');
  const sub = F.hold?'AWAITING DESIGN VERIFICATION':status==='HIJAU'?'SAFE FOR USE':status==='KUNING'?'USE WITH RESTRICTION':status==='MERAH'?'DO NOT USE':'AWAITING INSPECTION';
  const subID = F.hold?'MENUNGGU VERIFIKASI DESAIN':status==='HIJAU'?'AMAN DIGUNAKAN':status==='KUNING'?'PENGGUNAAN BERSYARAT':status==='MERAH'?'DILARANG DIGUNAKAN':'MENUNGGU INSPEKSI';
  const icon = status==='HIJAU'?'✓':status==='MERAH'?'✕':status==='KUNING'?'!':'…';
  const restrict = F.hold?'Analisis struktur indikatif belum terpenuhi ('+F.nCek+' pemeriksaan CEK). Jangan dibebani sesuai kelas beban sampai desain diverifikasi ahli perancah yang kompeten.'+(st.status==='KUNING'?' Tindak lanjuti juga temuan non-kritis checklist.':'')
    :status==='KUNING'?'Perancah dimodifikasi / belum lengkap. Wajib tie-off 100%. Lengkapi sebelum penggunaan penuh.':status==='MERAH'?'Perancah TIDAK AMAN. Dilarang dinaiki sampai diperbaiki dan diperiksa ulang.':status==='HIJAU'?'Perancah lengkap dan aman untuk akses sesuai kelas beban.':'Lengkapi inspeksi untuk menentukan status.';
  const recHigher = A.L2.kn > D.kn + 1e-9;
  const anTxt = A.ok?'Lolos indikatif (Beta)':'Perlu review (Beta)';
  const bars='<i></i>'.repeat(26);
  const front=`<div class="tag-card">
    <div class="tag-logobar"><img src="${LOGO_LIGHT_SM}" width="80" height="28" alt="PPAPI" onerror="this.onerror=null;this.src=LOGO_D"></div><div class="tag-sub">SCAFFOLD TAG · ${tagno}</div>
    <div class="tag-band" style="background:${F.c};color:${inkOn(F.c)}"><div class="tb-ic">${icon}</div><div class="tb-st">${subID}</div><div class="tb-sub">${sub}</div></div>
    <div class="tag-perf"></div>
    <div class="tag-body2">
      <div class="tag-row"><span class="k">Proyek</span><span class="v">${esc(val('f-proyek'))||'—'}</span></div>
      <div class="tag-row"><span class="k">Lokasi</span><span class="v">${esc(val('f-lokasi'))||'—'}</span></div>
      <div class="tag-row"><span class="k">Jenis</span><span class="v">${esc(val('f-jenis'))||'—'}</span></div>
      <div class="tag-row"><span class="k">Model</span><span class="v">${modelName(getModel())}</span></div>
      <div class="tag-row"><span class="k">Tinggi</span><span class="v">${val('f-tinggi')?esc(val('f-tinggi'))+' m':'—'}</span></div>
      <div class="tag-row"><span class="k">Kelas beban</span><span class="v">${D.en} · ${D.kn.toFixed(1).replace('.',',')} kN/bay (≈${kgBay} kg)</span></div>
      ${recHigher?`<div class="tag-row tag-flag"><span class="k">Rekomendasi Tahap 2</span><span class="v">${A.L2.cls} · ${nf(A.L2.kn,1)} kN/bay — lebih tinggi</span></div>`:''}
      <div class="tag-duty"><span class="${D.code==='RINGAN'?'on':''}">Light</span><span class="${D.code==='SEDANG'?'on':''}">Medium</span><span class="${D.code==='BERAT'?'on':''}">Heavy</span><span class="${D.code==='KHUSUS'?'on':''}">Special</span></div>
      <div class="tag-row"><span class="k">Analisis struktur</span><span class="v">${anTxt}</span></div>
      <div class="tag-row"><span class="k">Didirikan</span><span class="v">${tgl}</span></div>
      <div class="tag-row"><span class="k">Inspektor</span><span class="v">${esc(val('f-inspektor'))||'—'}</span></div>
      <div class="tag-row"><span class="k">Periksa ulang</span><span class="v">${next}</span></div>
      <div class="tag-row"><span class="k">Kritis gagal</span><span class="v">${st.critFail} / ${st.crit}</span></div>
      <div class="tag-bar">${bars}</div>
      <div class="tag-code">${tagno}</div>
    </div>
    <div class="tag-warn">PERINGATAN: Dilarang melepas atau memindahkan tag ini. Hanya personel berkompeten (Supervisor Perancah) yang boleh mengubah status.</div>
    <div class="tag-foot">PPAPI · Perkumpulan Praktisi &amp; Ahli Perancah Indonesia</div>
  </div>`;
  const back=`<div class="tag-card">
    <div class="tag-logobar"><img src="${LOGO_LIGHT_SM}" width="80" height="28" alt="PPAPI" onerror="this.onerror=null;this.src=LOGO_D"></div><div class="tag-sub">REKAMAN INSPEKSI</div>
    <div class="tag-body2">
      <div class="tag-state">Perancah ini telah diperiksa oleh personel yang berkompeten dan dinyatakan <b>${subID.toLowerCase()}</b> pada tanggal pemeriksaan terakhir. Catatan: ${restrict}</div>
      <table class="tag-rec"><thead><tr><th>Tanggal</th><th>Inspektor</th><th>Hasil</th></tr></thead><tbody>
        <tr><td>${tgl}</td><td>${esc(val('f-inspektor'))||'—'}</td><td>${status}${F.hold?' (desain)':''}</td></tr>
        <tr><td>&nbsp;</td><td></td><td></td></tr>
        <tr><td>&nbsp;</td><td></td><td></td></tr>
        <tr><td>&nbsp;</td><td></td><td></td></tr>
        <tr><td>&nbsp;</td><td></td><td></td></tr>
      </tbody></table>
      <div class="tag-row" style="margin-top:8px"><span class="k">Periksa ulang</span><span class="v">≤ 7 hari / cuaca ekstrem</span></div>
      <div class="tag-row"><span class="k">Acuan perhitungan</span><span class="v">BS EN 12811-1 · BS EN 74-1 · NASC TG20:21</span></div>
      <div class="tag-beta">Analisis struktur aplikasi PPAPI Scaffold v${APP_VERSION} (Beta) bersifat indikatif dan bukan sertifikasi desain.</div>
    </div>
    <div class="tag-warn">Melepas tag tanpa wewenang dapat membahayakan keselamatan dan melanggar prosedur K3.</div>
    <div class="tag-foot">PPAPI Scaffold · Tagging Perancah</div>
  </div>`;
  return `<div class="tag-wrap">${front}${back}</div>`;
}
function renderTag(){ document.getElementById('tag-preview').innerHTML = tagHTML(); }
function printTag(){
  renderTag();
  document.getElementById('print-tag-area').innerHTML = '<div style="padding:30px">'+tagHTML()+'</div>';
  window.print();
}

/* ---------- PDF ---------- */
function dwgSheetSVG(sheet){
  const keepS=dwgSheet, keepSel=dwgSel, keepVB={x:DWG_VB.x,y:DWG_VB.y,w:DWG_VB.w,h:DWG_VB.h};
  const keepBad=(typeof window!=='undefined'&&window.__dwgBad)?window.__dwgBad:[];
  const keepMag=(typeof window!=='undefined')?window.__mag:null;
  dwgSheet=sheet; dwgSel=null;
  if(typeof window!=='undefined'){ window.__dwgBad=[]; window.__mag=null; }
  const items=DWG[sheet]||[];
  let minx=1e9,miny=1e9,maxx=-1e9,maxy=-1e9;
  items.forEach(function(it){
    const pts=[{x:it.x,y:it.y}];
    if(it.len>0){ const e=endsOf(it); pts.push(e[0],e[1]); }
    if(it.x2!=null) pts.push({x:it.x2,y:it.y2});
    if(it.t==='note') pts.push({x:it.x+1.4,y:it.y-1});
    pts.forEach(function(p){ minx=Math.min(minx,p.x); maxx=Math.max(maxx,p.x); miny=Math.min(miny,p.y); maxy=Math.max(maxy,p.y); });
  });
  if(minx>maxx){ minx=0; maxx=16; miny=DWG_GY-8; maxy=DWG_GY+0.5; }
  if(sheet!=='atas') maxy=Math.max(maxy, Math.min(DWG_GY+0.8, DWG_H));
  minx-=1.4; maxx+=1.4; miny-=1.2; maxy+=0.6;
  let bw=Math.max(9,maxx-minx), bh=Math.max(6,maxy-miny);
  const cx=(minx+maxx)/2, cy=(miny+maxy)/2;
  let box={x:cx-bw/2, y:cy-bh/2, w:bw, h:bh};
  box.x=Math.max(-1.5,Math.min(DWG_W+1.5-bw,box.x));
  box.y=Math.max(-1.5,Math.min(DWG_H+1.5-bh,box.y));
  DWG_VB=box;
  const body='<rect x="'+pxm(box.x)+'" y="'+pxm(box.y)+'" width="'+pxm(box.w)+'" height="'+pxm(box.h)+'" fill="#ffffff"/>'+gridSVG()+items.slice().sort(function(a,b){ return ((a.ly||3)-(b.ly||3))||(a.id-b.id); }).map(itemSVG).join('');
  dwgSheet=keepS; dwgSel=keepSel; DWG_VB=keepVB;
  if(typeof window!=='undefined'){ window.__dwgBad=keepBad; window.__mag=keepMag; }
  let pw,ph;
  if(box.w>=box.h){ pw=1600; ph=Math.round(1600*box.h/box.w); } else { ph=1500; pw=Math.round(1500*box.w/box.h); }
  const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+pxm(box.x)+' '+pxm(box.y)+' '+pxm(box.w)+' '+pxm(box.h)+'" width="'+pw+'" height="'+ph+'">'+body+'</svg>';
  return {svg:svg, wm:box.w, hm:box.h, pw:pw, ph:ph};
}
function svgToPNG(svgStr,pw,ph){
  pw=pw||1600; ph=ph||900;
  return new Promise(function(res,rej){
    try{
      const img=new Image();
      img.onload=function(){
        try{
          const cv=document.createElement('canvas'); cv.width=pw; cv.height=ph;
          const cx=cv.getContext('2d'); cx.fillStyle='#ffffff'; cx.fillRect(0,0,pw,ph);
          cx.drawImage(img,0,0,pw,ph);
          res(cv.toDataURL('image/jpeg',0.9));   /* B7: JPEG (sebelumnya PNG RGBA tanpa kompresi → PDF 10 MB) */
        }catch(e){ rej(e); }
      };
      img.onerror=rej;
      img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svgStr);
    }catch(e){ rej(e); }
  });
}
function imgDims(durl){
  return new Promise(function(res,rej){
    const img=new Image();
    img.onload=function(){ res({w:img.width||4,h:img.height||3}); };
    img.onerror=rej; img.src=durl;
  });
}
function pdfSan(s){ return String(s).split(' · ').join(', ').split('≤').join('<=').split('≥').join('>=').split('≈').join('~').split('→').join('->').split('·').join('.').split('—').join('-').split('–').join('-').split('½').join('1/2').split('…').join('...').split('²').join('2').split('λ̄').join('lambda').split('χ').join('chi'); }
function emblemPDF(doc,cx,cy,r){
  const k=0.8660254*r;
  const segs=[[k,0.5*r],[0,r],[-k,0.5*r],[-k,-0.5*r],[0,-r],[k,-0.5*r]];
  doc.setFillColor(17,17,19); doc.setDrawColor(185,185,191); doc.setLineWidth(0.8);
  doc.lines(segs, cx, cy-r, [1,1], 'FD', true);
}
/* Perbaikan B8: baris "label : nilai" di PDF — label diperkecil/dilebarkan bila perlu dan
   nilai dipotong sesuai lebar kolom, sehingga label tidak lagi menimpa nilai. */
function pdfKV(doc,label,value,x,y,labelW,cellW){
  const L=String(label).toUpperCase();
  doc.setFont('helvetica','bold'); doc.setTextColor(92,92,99);
  let fs=8.6; doc.setFontSize(fs);
  while(doc.getTextWidth(L)>labelW-2 && fs>7.2){ fs=Math.round((fs-0.2)*10)/10; doc.setFontSize(fs); }
  const lw=Math.min(cellW*0.55, Math.max(labelW, doc.getTextWidth(L)+2.5));
  doc.text(L,x,y);
  doc.setFontSize(8.6); doc.setFont('helvetica','normal'); doc.setTextColor(17,17,19);
  const avail=cellW-lw-1;
  let v=String(value==null||value===''?'-':value);
  if(doc.getTextWidth(v)>avail){ while(v.length>1 && doc.getTextWidth(v+'...')>avail) v=v.slice(0,-1); v=v.replace(/\s+$/,'')+'...'; }
  doc.text(v,x+lw,y);
}
/* Perbaikan B15: pustaka jsPDF dimuat saat laporan dibuat (bukan memblokir setiap kunjungan).
   Keamanan: halaman ini satu origin dengan portal (sesi Firebase, konsol admin, localStorage), sehingga
   skrip CDN wajib memakai Subresource Integrity — berkas yang berubah satu bita pun ditolak peramban.
   Hash SHA-512 jspdf.umd.min.js 2.5.1 (cdnjs) — dicatat juga di aplikasi/CATATAN.md §7. */
const JSPDF_SRC='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
const JSPDF_SRI='sha512-qZvrmS2ekKPF2mSznTQsxqPgnpkI4DNTlrdUmTzrDgektczlKNRRhy5X5AAOnx5S09ydFYWWNSfcEqDTTHgtNA==';
let jspdfLoading=null;
function ensureJsPDF(){
  if(window.jspdf&&window.jspdf.jsPDF) return Promise.resolve();
  if(jspdfLoading) return jspdfLoading;
  jspdfLoading=new Promise(function(res,rej){
    const s=document.createElement('script');
    s.integrity=JSPDF_SRI; s.crossOrigin='anonymous'; s.referrerPolicy='no-referrer';
    s.src=JSPDF_SRC;
    s.onload=function(){ (window.jspdf&&window.jspdf.jsPDF)?res():rej(new Error('jspdf')); };
    s.onerror=function(){ jspdfLoading=null; rej(new Error('jspdf')); };
    document.head.appendChild(s);
  });
  return jspdfLoading;
}
let pdfBusy=false;
async function buildPDF(){
  if(pdfBusy) return;
  pdfBusy=true;
  const btns=document.querySelectorAll('[data-pdf-btn]');
  btns.forEach(function(b){ b.disabled=true; b.setAttribute('aria-busy','true'); });
  try{
    await ensureJsPDF();
    await buildPDFNow();
    logAct('Buat laporan PDF');
  }catch(e){
    notify(e&&e.message==='jspdf' ? 'Pustaka PDF tidak dapat dimuat. Periksa koneksi internet, lalu coba lagi.' : 'Laporan PDF gagal dibuat. Silakan coba lagi.','error');
    if(window.console) console.warn('[PPAPI Scaffold] PDF:', e);
  }finally{
    pdfBusy=false;
    btns.forEach(function(b){ b.disabled=false; b.removeAttribute('aria-busy'); });
  }
}
