      const ans=ansOf(parseInt(p[0],10),parseInt(p[1],10)); const ansT= ans==='ok'?'Sesuai':ans==='no'?'Tidak Sesuai':ans==='na'?'N/A':'Belum dinilai';
      if(y>228){doc.addPage();y=20;}
      try{ doc.addImage(state.photos[k],'JPEG',M,y,66,49); }catch(e){ doc.setDrawColor(220,220,223); doc.rect(M,y,66,49); }
      doc.setFont('helvetica','bold'); doc.setFontSize(8.5); doc.setTextColor(17,17,19);
